<template>
  <section class="model-gateway">
    <header class="gateway-header"><div><p class="eyebrow">MODEL CENTER / GATEWAY</p><h1>统一模型网关</h1><p>一个 SmartOps Key 访问已授权的模型分组，Provider 密钥留在服务端。</p></div><span class="gateway-state"><i />FOUNDATION</span></header>
    <nav class="gateway-tabs" aria-label="模型网关视图"><button v-for="tab in tabs" :key="tab.id" :class="{ active: view === tab.id }" type="button" @click="select(tab.id)">{{ tab.label }}<small>{{ tab.cn }}</small></button></nav>
    <div v-if="view === 'overview'" class="gateway-grid"><section class="gateway-panel gateway-panel--wide"><p class="eyebrow">OPENAI COMPATIBLE</p><h2>统一调用入口</h2><code>POST /v1/chat/completions</code><p>网关按模型组路由，并记录不含请求正文的调用元数据。</p><div class="gateway-flow"><span>VIRTUAL KEY</span><b>→</b><span>MODEL GROUP</span><b>→</b><span>PROVIDER</span></div></section><section class="gateway-panel"><p class="eyebrow">CURRENT SPACE</p><h2>模型接入</h2><p>现有模型连接继续使用 Astra6 的 MODELS 导航。</p><RouterLink to="/model-settings">打开模型接入 →</RouterLink></section><section class="gateway-panel"><p class="eyebrow">GOVERNANCE</p><h2>权限与审计</h2><p>虚拟 Key、模型分组和 Provider 凭据在服务端管理。</p></section></div>
    <section v-else-if="view === 'keys'" class="gateway-panel gateway-management"><div class="management-heading"><div><p class="eyebrow">VIRTUAL KEYS</p><h2>虚拟 Key 管理</h2><p>完整 Key 只在创建时显示，列表仅保留前缀和状态。</p></div><button class="gateway-action" type="button" :disabled="keySaving" @click="createKey">{{ keySaving ? '创建中' : '创建个人 Key' }}</button></div><p v-if="keyNotice" class="gateway-notice">{{ keyNotice }}</p><p v-if="keyError" class="gateway-error">{{ keyError }}</p><div v-if="newKey" class="new-key"><span>新 Key（仅显示一次）</span><code>{{ newKey }}</code><button type="button" @click="copyKey">复制</button></div><div v-if="keysLoading" class="gateway-empty-state">正在读取 Key...</div><div v-else-if="keys.length" class="key-list"><div v-for="item in keys" :key="item.id" class="key-row"><div><strong>{{ item.name }}</strong><code>{{ item.prefix }}...</code><small>{{ quotaText(item) }}</small></div><span :class="['key-status', { revoked: item.revoked }]">{{ item.revoked ? 'REVOKED' : 'ACTIVE' }}</span><div v-if="!item.revoked" class="key-actions"><GatewayQuotaEditor :item="item" @saved="applyQuota(item, $event)" /><button type="button" :disabled="keyBusy === item.id" @click="revokeKey(item)">{{ keyBusy === item.id ? '处理中' : '撤销' }}</button></div></div></div><div v-else class="gateway-empty-state">还没有个人 Key。</div></section>
    <section v-else-if="view === 'audit'" class="gateway-panel gateway-management"><div class="management-heading"><div><p class="eyebrow">AUDIT / HEALTH</p><h2>网关运行观测</h2><p>近 24 小时统计和路由状态，仅展示脱敏元数据。</p></div><button class="gateway-action" type="button" :disabled="auditLoading" @click="loadAudit">刷新</button></div><p v-if="auditError" class="gateway-error">{{ auditError }}</p><div class="audit-metrics"><div><span>REQUESTS</span><strong>{{ audit.summary.calls }}</strong></div><div><span>SUCCESS</span><strong>{{ successRate }}%</strong></div><div><span>AVG LATENCY</span><strong>{{ audit.summary.latencyMs }} ms</strong></div><div><span>TOKENS</span><strong>{{ audit.summary.tokens }}</strong></div></div><div class="route-search"><input v-model.trim="routeSlug" placeholder="模型组标识，例如 ops-default"><button type="button" :disabled="!routeSlug" @click="loadRouteHealth">查看路由</button></div><p v-if="routeError" class="gateway-error">{{ routeError }}</p><div v-if="routeHealth.length" class="key-list"><div v-for="item in routeHealth" :key="item.id" class="key-row"><div><strong>连接 #{{ item.connectionId }}</strong><code>优先级 {{ item.priority }} · 失败 {{ item.failureCount }} 次</code></div><span :class="['key-status', { revoked: !item.healthy }]">{{ item.healthy ? 'READY' : 'OPEN' }}</span></div></div><div class="key-list"><div v-for="entry in audit.recent" :key="entry.group + entry.createdAt" class="key-row"><div><strong>{{ entry.group }}</strong><code>{{ entry.createdAt }}</code></div><span :class="['key-status', { revoked: entry.status !== 'SUCCESS' }]">{{ entry.status }}</span><span>{{ entry.durationMs }} ms</span></div></div><p v-if="!audit.recent.length && !auditLoading" class="gateway-empty-state">暂无调用记录。</p></section>
    <section v-else class="gateway-panel gateway-management"><div class="management-heading"><div><p class="eyebrow">MODEL GROUPS</p><h2>模型分组与路由</h2><p>模型组使用已有模型连接，并在同一操作区配置 24 小时配额。</p></div><RouterLink class="gateway-link" to="/model-settings">管理模型连接 →</RouterLink></div><GatewayGroupForm :saving="groupSaving" @submit="saveGroup" /><p v-if="groupNotice" class="gateway-notice">{{ groupNotice }}</p><p v-if="groupError" class="gateway-error">{{ groupError }}</p></section>
    <section v-if="view === 'audit' && routeHealth.length" class="gateway-panel gateway-management route-admin-panel"><div class="management-heading"><div><p class="eyebrow">ROUTE CONTROL</p><h2>路由控制</h2><p>仅管理当前模型组查询到的路由。</p></div></div><div class="key-list"><div v-for="item in routeHealth" :key="`control-${item.id}`" class="key-row"><div><strong>连接 #{{ item.connectionId }}</strong><code>优先级 {{ item.priority }} · 权重 {{ item.weight }}</code></div><span :class="['key-status', { revoked: !item.enabled || !item.healthy }]">{{ item.enabled ? (item.healthy ? 'READY' : 'OPEN') : 'DISABLED' }}</span><div class="key-actions"><button type="button" @click="toggleRoute(item)">{{ item.enabled ? '禁用' : '启用' }}</button><button type="button" @click="removeRoute(item)">删除</button></div></div></div></section>
    <section v-if="view === 'groups'" class="gateway-panel gateway-management group-list-panel"><div class="management-heading"><div><p class="eyebrow">PERSONAL GROUPS</p><h2>我的模型组</h2><p>模型组和 Provider 路由仅对当前用户可见。</p></div><button class="gateway-action" type="button" @click="loadGroups">刷新</button></div><div v-if="groupsLoading" class="gateway-empty-state">正在读取模型组...</div><div v-else-if="groups.length" class="group-list"><article v-for="item in groups" :key="item.slug" class="group-item"><div class="group-item__head"><div><strong>{{ item.name }}</strong><code>{{ item.slug }}</code></div><span :class="['key-status', { revoked: !item.enabled }]">{{ item.enabled ? 'ACTIVE' : 'DISABLED' }}</span><div class="key-actions"><button type="button" :disabled="groupBusy === item.slug" @click="renameGroup(item)">重命名</button><button type="button" :disabled="groupBusy === item.slug" @click="removeGroup(item)">删除</button></div></div><p class="group-meta">{{ quotaText(item) }}</p><div class="route-inline"><input v-model.number="routeDrafts[item.id].priority" type="number" min="0" max="10000" placeholder="优先级"><input v-model.number="routeDrafts[item.id].weight" type="number" min="1" max="1000" placeholder="权重"><button type="button" @click="editRoute(item, routeDrafts[item.id])">保存路由参数</button></div></article></div><p v-else class="gateway-empty-state">还没有个人模型组。</p></section>
  </section>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import GatewayQuotaEditor from '../../components/model/GatewayQuotaEditor.vue'
import GatewayGroupForm from '../../components/model/GatewayGroupForm.vue'
import { listGatewayKeys, createGatewayKey, revokeGatewayKey, configureGatewayGroup, listGatewayGroups, updateGatewayGroup, deleteGatewayGroup, updateGatewayGroupQuota, getGatewayAnalytics, getGatewayRoutes, addGatewayRoute, updateGatewayRoute, updateGatewayRouteStatus, deleteGatewayRoute } from '../../api/model'
const route = useRoute(), router = useRouter(), tabs = [{ id: 'overview', label: 'OVERVIEW', cn: '网关总览' }, { id: 'groups', label: 'MODEL GROUPS', cn: '模型分组' }, { id: 'keys', label: 'VIRTUAL KEYS', cn: '虚拟 Key' }, { id: 'audit', label: 'AUDIT / HEALTH', cn: '运行观测' }]
const view = computed(() => ['groups', 'keys', 'audit'].includes(route.query.view) ? route.query.view : 'overview'), unwrap = response => response?.data ?? response
const keys = ref([]), keysLoading = ref(false), keySaving = ref(false), keyBusy = ref(null), keyError = ref(''), keyNotice = ref(''), newKey = ref(''), groups = ref([]), groupsLoading = ref(false), groupSaving = ref(false), groupError = ref(''), groupNotice = ref(''), groupBusy = ref(null), routeDrafts = ref({})
const audit = ref({ summary: { calls: 0, successes: 0, latencyMs: 0, tokens: 0 }, recent: [] }), auditLoading = ref(false), auditError = ref(''), routeSlug = ref(''), routeHealth = ref([]), routeError = ref('')
const successRate = computed(() => audit.value.summary.calls ? Math.round(audit.value.summary.successes / audit.value.summary.calls * 100) : 0)
function select(value) { router.replace({ path: '/model-gateway', query: value === 'overview' ? {} : { view: value } }) }
function quotaText(item) { return `${item.requestLimit24h > -1 ? item.requestLimit24h + ' req/24h' : 'unlimited requests'} · ${item.tokenLimit24h > -1 ? item.tokenLimit24h + ' tokens/24h' : 'unlimited tokens'}` }
function applyQuota(item, payload) { item.requestLimit24h = payload.requestLimit24h == null ? -1 : payload.requestLimit24h; item.tokenLimit24h = payload.tokenLimit24h == null ? -1 : payload.tokenLimit24h; keyNotice.value = 'Key 配额已更新。' }
async function loadKeys() { keysLoading.value = true; try { const value = unwrap(await listGatewayKeys()); keys.value = Array.isArray(value) ? value : (value?.items || []) } catch (error) { keyError.value = error.message || '无法读取 Key' } finally { keysLoading.value = false } }
async function createKey() { keySaving.value = true; keyError.value = ''; try { const value = unwrap(await createGatewayKey({ name: `personal-${new Date().toISOString().slice(0, 10)}` })); newKey.value = value.key; keyNotice.value = 'Key 已创建，请立即复制并保存。'; await loadKeys() } catch (error) { keyError.value = error.message || '创建 Key 失败' } finally { keySaving.value = false } }
async function revokeKey(item) { keyBusy.value = item.id; try { await revokeGatewayKey(item.id); item.revoked = true; keyNotice.value = 'Key 已撤销。' } catch (error) { keyError.value = error.message || '撤销 Key 失败' } finally { keyBusy.value = null } }
async function copyKey() { try { await navigator.clipboard.writeText(newKey.value); keyNotice.value = 'Key 已复制。' } catch { keyNotice.value = '请手动复制 Key。' } }
async function saveGroup(payload) { groupSaving.value = true; groupError.value = ''; try { await configureGatewayGroup(payload); await updateGatewayGroupQuota(payload.slug, { requestLimit24h: payload.requestLimit24h, tokenLimit24h: payload.tokenLimit24h }); groupNotice.value = '模型组和配额已保存。' } catch (error) { groupError.value = error.message || '保存模型组失败' } finally { groupSaving.value = false } }
async function loadAudit() { auditLoading.value = true; try { audit.value = unwrap(await getGatewayAnalytics()) } catch (error) { auditError.value = error.message || '无法读取网关统计' } finally { auditLoading.value = false } }
async function loadRouteHealth() { routeError.value = ''; try { routeHealth.value = unwrap(await getGatewayRoutes(routeSlug.value)) } catch (error) { routeError.value = error.message || '无法读取路由状态' } }
async function toggleRoute(item) { routeError.value = ''; try { await updateGatewayRouteStatus(routeSlug.value, item.id, !item.enabled); item.enabled = !item.enabled } catch (error) { routeError.value = error.message || '无法更新路由状态' } }
async function removeRoute(item) { routeError.value = ''; try { await deleteGatewayRoute(routeSlug.value, item.id); routeHealth.value = routeHealth.value.filter(route => route.id !== item.id) } catch (error) { routeError.value = error.message || '无法删除路由' } }
async function loadGroups() { groupsLoading.value = true; try { const value = unwrap(await listGatewayGroups()); groups.value = Array.isArray(value) ? value : (value?.items || []); routeDrafts.value = Object.fromEntries(groups.value.map(item => [item.id, { priority: 100, weight: 100 }])) } catch (error) { groupError.value = error.message || '无法读取模型组' } finally { groupsLoading.value = false } }
async function renameGroup(item) { const name = window.prompt('模型组名称', item.name); if (!name || name.trim() === item.name) return; groupBusy.value = item.slug; try { await updateGatewayGroup(item.slug, { name: name.trim() }); item.name = name.trim(); groupNotice.value = '模型组名称已更新。' } catch (error) { groupError.value = error.message || '无法更新模型组' } finally { groupBusy.value = null } }
async function removeGroup(item) { if (!window.confirm(`删除模型组 ${item.slug}？`)) return; groupBusy.value = item.slug; try { await deleteGatewayGroup(item.slug); groups.value = groups.value.filter(group => group.slug !== item.slug); groupNotice.value = '模型组已删除。' } catch (error) { groupError.value = error.message || '无法删除模型组' } finally { groupBusy.value = null } }
async function editRoute(group, routeItem) { const draft = routeDrafts.value[routeItem.id] || { priority: routeItem.priority, weight: routeItem.weight }; try { await updateGatewayRoute(group.slug, routeItem.id, { priority: Number(draft.priority), weight: Number(draft.weight) }); routeItem.priority = Number(draft.priority); routeItem.weight = Number(draft.weight); groupNotice.value = '路由参数已更新。' } catch (error) { groupError.value = error.message || '无法更新路由' } }
onMounted(() => { if (view.value === 'keys') loadKeys(); if (view.value === 'audit') loadAudit(); if (view.value === 'groups') loadGroups() })
</script>
<style scoped>
