art-accent-foreground);cursor:pointer}.gateway-notice{color:var(--smart-primary-strong)!important}.gateway-error{color:var(--smart-danger,#f08d9c)!important}.new-key{display:grid;grid-template-columns:auto 1fr auto;gap:12px;padding:14px;border:1px solid var(--smart-primary-strong)}.new-key code,.key-row code{overflow:auto;color:var(--smart-muted);font:11px var(--font-mono)}.key-row code,.key-row small{display:block;margin-top:5px}.key-list{display:grid;border-top:1px solid var(--smart-border)}.key-row{display:grid;grid-template-columns:1fr auto auto;gap:14px;align-items:center;padding:14px 0;border-bottom:1px solid var(--smart-border)}.key-status{font:10px var(--font-mono);color:var(--smart-primary-strong)}.key-status.revoked{color:var(--smart-muted)}.key-row button{min-height:32px;padding:6px 9px;border:1px solid var(--smart-border);border-radius:6px;background:var(--smart-surface);color:var(--smart-text)}.gateway-empty-state{padding:24px 0;color:var(--smart-muted);font-size:13px}.group-form,.route-search{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:12px;align-items:end}.group-form label{display:grid;gap:7px;font-size:12px;color:var(--smart-muted)}.group-form input,.route-search input{height:40px;padding:0 10px;border:1px solid var(--smart-border);border-radius:7px;background:var(--smart-bg);color:var(--smart-text)}.audit-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.audit-metrics div{padding:14px;border:1px solid var(--smart-border)}.audit-metrics span{display:block;color:var(--smart-muted);font:10px var(--font-mono)}.audit-metrics strong{display:block;margin-top:8px;font-size:20px}.route-search{grid-template-columns:1fr auto}.route-search button{min-height:36px;padding:8px 11px;border:1px solid var(--smart-border);border-radius:7px;background:var(--smart-surface);color:var(--smart-text)}button:focus-visible,input:focus-visible,a:focus-visible{outline:2px solid var(--smart-primary-strong);outline-offset:3px}@media(max-width:700px){.gateway-header,.management-heading,.group-form,.route-search{display:grid;grid-template-columns:1fr}.gateway-grid{grid-template-columns:1fr}.gateway-panel--wide{grid-row:auto}.new-key{grid-template-columns:1fr}.key-row{grid-template-columns:1fr auto}.audit-metrics{grid-template-columns:1fr 1fr}}
</style>
